CREATE OR REPLACE VIEW active_users AS
SELECT id, email, display_name
FROM users
WHERE deleted_at IS NULL;

CREATE OR REPLACE FUNCTION active_users_ins()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO users (email, display_name)
  VALUES (NEW.email, NEW.display_name)
  RETURNING id INTO NEW;
  RETURN NEW;
END;
$$;

CREATE TRIGGER active_users_ins_trig
  INSTEAD OF INSERT ON active_users
  FOR EACH ROW
  EXECUTE FUNCTION active_users_ins();
